scwin.onpageunload = function() {};
scwin.trigger1_onclick = function(e) {
    dataList1.removeAll();
};
scwin.trigger2_onclick = function(e) {
    grd.setGridHeight("500px");
};
scwin.trigger3_onclick = function(e) {
    grd.setGridHeight("300px");
};
scwin.trigger4_onclick = function(e) {
    grd.setGridHeight("100px");
};
scwin.checkVal = function() {
    return WebSquare.wUnit.getJq(WebSquare.wUnit.getDomById($p.id + 'grd_body_tbody').getElementsByTagName('tr')[0]).hasClass('w2grid_hidedRow');
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger4').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
